"A_cl = [-0.8, 1.0; -6.2, -1.9];
B_cl = [0.0; 1.0];
C_cl = [1.0, 0.0];

dt = 0.01;
T = 30;
t = (0:dt:T)';
N = length(t);

Ad = expm(A_cl*dt);
I2 = eye(2);
Bd = A_cl \ ((Ad - I2)*B_cl);

x = zeros(2, N);
y = zeros(N, 1);
y(1) = C_cl * x(:,1);
for k = 1:N-1
    x(:,k+1) = Ad*x(:,k) + Bd*1.0;
    y(k+1) = C_cl * x(:,k+1);
end

y_inf = -C_cl * (A_cl \ B_cl);

% Rise time: first 10% to first 90% crossing of y_inf (linear interpolation)
target_10 = 0.1 * y_inf;
target_90 = 0.9 * y_inf;

t_10 = NaN;
t_90 = NaN;

for k = 2:N
    if y(k-1) < target_10 && y(k) >= target_10
        t_10 = t(k-1) + (target_10 - y(k-1))/(y(k) - y(k-1)) * dt;
        break;
    end
end

for k = 2:N
    if y(k-1) < target_90 && y(k) >= target_90
        t_90 = t(k-1) + (target_90 - y(k-1))/(y(k) - y(k-1)) * dt;
        break;
    end
end

rise_time_s = t_90 - t_10;

% Percent overshoot
max_y = max(y);
overshoot_pct = (max_y - y_inf)/abs(y_inf) * 100;

% 2% settling time: time of LAST grid sample where |y - y_inf| > 0.02*|y_inf|
tol = 0.02 * abs(y_inf);
exceeded = abs(y - y_inf) > tol;
idx_settling = find(exceeded, 1, 'last');
if isempty(idx_settling)
    settling_time_s = 0;
else
    settling_time_s = t(idx_settling);
end

result.rise_time_s = rise_time_s;
result.overshoot_pct = overshoot_pct;
result.settling_time_s = settling_time_s;

fid = fopen('result.json', 'w');
fwrite(fid, jsonencode(result));
fclose(fid);"
